float calibrationFactor = 1.0; // Initial calibration factor

void setup() {
  Serial.begin(9600);
  Wire.begin();
  delay(1000); // Wait for DHT22 to stabilize

  // Perform calibration
  for (int i = 0; i < 10; i++) {
    int sensorValue = dht.dht22Read(DHT_PIN);
    float temperature = dht.temperature;
    float humidity = dht.humidity;

    // Calculate the error between the measured and expected values
    float tempError = abs(temperature - 20.0); // Expected temperature is 20°C
    float humidityError = abs(humidity - 60.0); // Expected humidity is 60%

    // Update the calibration factor
    calibrationFactor += (tempError + humidityError) * 0.1;
    delay(1000);
  }

  Serial.print("Calibration factor: ");
  Serial.println(calibrationFactor);
}

void loop() {
  // Use the calibration factor to adjust the readings
  float temperature = dht.temperature * calibrationFactor;
  float humidity = dht.humidity * calibrationFactor;

  Serial.print("Temperature: ");
  Serial.print(temperature);
  Serial.println("°C");

  Serial.print("Humidity: ");
  Serial.print(humidity);
  Serial.println("%");

  delay(1000);
}
```
